// src/app/components/empleado-lista/empleado-lista.component.ts
import { Component, OnInit } from '@angular/core';
import { Empleado } from '../../models/empleado.model';
import { EmpleadoService } from '../../services/empleado.service';

@Component({
  selector: 'app-empleado-lista',
  templateUrl: './empleado-lista.component.html',
  styleUrls: ['./empleado-lista.component.css']
})
export class EmpleadoListaComponent implements OnInit {
  // Propiedades expuestas a la Vista (Estado local)
  titulo: string = 'Nómina de Empleados de la Empresa';
  listaEmpleados: Empleado[] = [];

  // Inyección de Dependencias: Conecta el Controlador con el Modelo
  constructor(private empleadoService: EmpleadoService) {}

  // Hook del ciclo de vida para cargar datos del Modelo
  ngOnInit(): void {
    this.cargarDatos();
  }

  cargarDatos() {
    this.empleadoService.getEmpleados().subscribe(data => {
      this.listaEmpleados = data;
    });
  }

  // Manejador de evento invocado desde la Vista
  borrarEmpleado(id: number | undefined) {
    if (id) {
      this.empleadoService.eliminarEmpleado(id).subscribe(() => {
        this.cargarDatos();
      });
    }
  }
}

<!-- src/app/components/empleado-lista/empleado-lista.component.html -->
<div class="card-container">
  <h2>{{ titulo }}</h2>
  <table *ngIf="listaEmpleados.length > 0" class="tabla-mvc">
    <thead>
      <tr>
        <th>ID</th>
        <th>Nombre</th>
        <th>Cargo</th>
        <th>Departamento</th>
        <th>Salario ($)</th>
        <th>Acción</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let emp of listaEmpleados">
        <td>{{ emp.id }}</td>
        <td>{{ emp.nombre }}</td>
        <td>{{ emp.cargo }}</td>
        <td>{{ emp.departamento }}</td>
        <td>${{ emp.salario }}</td>
        <td>
          <button (click)="borrarEmpleado(emp.id)" class="btn-eliminar">Eliminar</button>
        </td>
      </tr>
    </tbody>
  </table>
  <p *ngIf="listaEmpleados.length === 0" class="alerta">
    No hay registros de empleados en el Modelo.
  </p>
</div>
